// Este código é seguro e não permite SQL Injection
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class BancoDeDados {
    public static void main(String[] args) {
        // Conectar ao banco de dados
        Connection conexao = DriverManager.getConnection("jdbc:mysql://localhost:3306/banco", "usuário", "senha");

        // Usar parâmetros nomeados para evitar SQL Injection
        String sql = "SELECT * FROM usuários WHERE nome = ?";

        try (PreparedStatement statement = conexao.prepareStatement(sql)) {
            statement.setString(1, args[0]);
            ResultSet resultados = statement.executeQuery();
            while (resultados.next()) {
                System.out.println(resultados.getString("nome"));
            }
        } catch (SQLException e) {
            System.out.println("Erro ao executar SQL: " + e.getMessage());
        } finally {
            try {
                conexao.close();
            } catch (SQLException e) {
                System.out.println("Erro ao fechar a conexão: " + e.getMessage());
            }
        }
    }
}
```

